def test_merge_intervals_invalid_interval_single():
    intervals = [(5, 3)]
    try:
        merge_intervals(intervals)
    except ValueError as e:
        assert str(e) == "invalid interval"

def test_merge_intervals_invalid_interval_multiple():
    intervals = [(1, 2), (5, 3), (4, 5)]
    try:
        merge_intervals(intervals)
    except ValueError as e:
        assert str(e) == "invalid interval"

def test_merge_intervals_all_invalid():
    intervals = [(5, 3), (2, 1)]
    try:
        merge_intervals(intervals)
    except ValueError as e:
        assert str(e) == "invalid interval"

def test_merge_intervals_valid_then_invalid():
    intervals = [(1, 2), (5, 3)]
    try:
        merge_intervals(intervals)
    except ValueError as e:
        assert str(e) == "invalid interval"

def test_merge_intervals_invalid_then_valid():
    intervals = [(5, 3), (1, 2)]
    try:
        merge_intervals(intervals)
    except ValueError as e:
        assert str(e) == "invalid interval"

def test_merge_intervals_whitespace_in_error_message():
    intervals = [(5, 3)]
    try:
        merge_intervals(intervals)
    except ValueError as e:
        assert str(e) == 'invalid interval'
